{
  "case_id": "xsu_sg_009_medical_documentation_content",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret gengiver korrekt kernen i afsnit 4.2: dokumentation af varig funktionsnedsættelse og beskrivelse, udrednings- og behandlingsforløb samt de seks punkter. Det angiver, at oplysningerne medtages når de findes i journalen eller anden eksisterende lægefaglig dokumentation. Det gør hverken diagnose alene tilstrækkelig eller diagnose ubetinget krævet, og det fremstiller ikke behandling som valgfrie alternativer. Der er ingen væsentlig juridisk fejl."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret dækker næsten alle kritiske elementer: varig funktionsnedsættelse og beskrivelse, udrednings-/sygdoms-/behandlingsforløb, daglig funktion, diagnose, igangværende og planlagt behandling, erhvervsevne og tilgængelighed i journalen. Det nævner dog ikke eksplicit kravet om, at dokumentationen skal være relevant og aktuel, og det udelader funktionsnedsættelsens art og grad. Begge indgår i det første kritiske element. Svaret siger heller ikke klart, at oplysningerne skal fremsendes; det siger kun, at dokumentationen 'bør' indeholde dem."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvad den lægelige dokumentation skal beskrive, og indeholder ikke irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, f.eks. vejledningens afsnit 4.2 eller SU-bekendtgørelsens § 37. Det henviser kun generelt til journalen."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om kilden støtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Svaret tilføjer ikke nogen væsentlig regel, betingelse, myndighed eller retsvirkning, som mangler støtte i de frosne kilder. Indholdet svarer til afsnit 4.2."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Forbeholdene 'hvis en er stillet' (diagnose) og 'hvis det er muligt at beskrive' (erhvervsevne) er bevaret. Forbeholdet om tilgængelighed i journalen eller anden eksisterende lægefaglig dokumentation er også med. Forbeholdet 'hvis planlagt' for behandling er kun delvist udtrykt, via 'eventuelt planlagt behandling'. Det anses for tilstrækkeligt."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: først hovedkravene, derefter en liste over indholdet under forudsætning af tilgængelighed. Der er ingen modsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Kilden bruger 'skal' for at fremsende oplysningerne, når de er tilgængelige i journalen. Svaret omformulerer det til 'bør', hvilket svækker pligten til en anbefaling. Det er en upræcis modalitet i forhold til kilden og rubrikken."
    }
  },
  "xhaile_coverage": {
    "A39": {
      "label": "yes",
      "reason": "Svaret nævner 'diagnosen, hvis en er stillet', hvilket svarer til punktet og bevarer forbeholdet."
    },
    "A41": {
      "label": "yes",
      "reason": "Svaret nævner 'sygdoms- og behandlingsforløbet' og udrednings- og behandlingsforløbet."
    },
    "A42": {
      "label": "yes",
      "reason": "Behandlingsforløbet er nævnt sammen med sygdomsforløbet og i afsnittet om udrednings- og behandlingsforløb."
    },
    "A45": {
      "label": "yes",
      "reason": "Svaret nævner 'igangværende og eventuelt planlagt behandling', hvilket dækker planlagt behandling med forbehold."
    },
    "A47": {
      "label": "yes",
      "reason": "Svaret nævner påvirkningen af erhvervsevnen, 'hvis det er muligt at beskrive'."
    }
  },
  "overall_notes": "Indholdsmæssigt er svaret nøjagtigt og dækker alle XHAILe-punkterne. Det angiver dog ingen kilde, hvilket giver C04 not_met og C05/C06 not_assessable. Det udelader aktualitet og funktionsnedsættelsens art og grad, og 'bør' svækker kildens 'skal' (C02 og C10 not_met)."
}

